namespace ArgueBot.Core.Database
{
    internal static class DebateSchema
    {
        internal static string Version14 { get { return Create.Replace("compaction_recipient_id TEXT NOT NULL DEFAULT '', ", "").Replace("rebuild_from_originals INTEGER NOT NULL DEFAULT 0, ", "").Replace("repair INTEGER NOT NULL DEFAULT 0, ", ""); } }
        internal const string Create = """
CREATE TABLE IF NOT EXISTS debate_state(id TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE, tenant_id TEXT NOT NULL, mode TEXT NOT NULL, phase TEXT NOT NULL DEFAULT 'question', orchestrator_id TEXT NOT NULL, context_epoch BIGINT NOT NULL DEFAULT 0, roster_revision BIGINT NOT NULL DEFAULT 1, question TEXT NOT NULL DEFAULT '', proposal_id TEXT NOT NULL DEFAULT '', summary_id TEXT NOT NULL DEFAULT '', resume_phase TEXT NOT NULL DEFAULT '', compaction_recipient_id TEXT NOT NULL DEFAULT '', rebuild_from_originals INTEGER NOT NULL DEFAULT 0, invocations INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL, FOREIGN KEY(tenant_id,run_id) REFERENCES runs(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,orchestrator_id) REFERENCES profiles(tenant_id,id));
CREATE TABLE IF NOT EXISTS debate_members(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, run_id TEXT NOT NULL, profile_id TEXT NOT NULL, position INTEGER NOT NULL, joined_revision BIGINT NOT NULL, left_revision BIGINT, active INTEGER NOT NULL DEFAULT 1, created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL, UNIQUE(run_id,profile_id), FOREIGN KEY(tenant_id,run_id) REFERENCES runs(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,profile_id) REFERENCES profiles(tenant_id,id));
CREATE INDEX IF NOT EXISTS ix_debate_members_active ON debate_members(tenant_id,run_id,active,position);
CREATE TABLE IF NOT EXISTS debate_attempts(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL UNIQUE, tenant_id TEXT NOT NULL, purpose TEXT NOT NULL, context_epoch BIGINT NOT NULL, roster_revision BIGINT NOT NULL, proposal_id TEXT NOT NULL DEFAULT '', repair INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL, FOREIGN KEY(tenant_id,attempt_id) REFERENCES generation_attempts(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS debate_proposals(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, run_id TEXT NOT NULL, message_id TEXT NOT NULL, content TEXT NOT NULL, digest TEXT NOT NULL, context_epoch BIGINT NOT NULL, roster_revision BIGINT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,run_id) REFERENCES runs(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,message_id) REFERENCES messages(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS debate_agreements(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, proposal_id TEXT NOT NULL, profile_id TEXT NOT NULL, message_id TEXT NOT NULL, position TEXT NOT NULL, rationale TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL, UNIQUE(proposal_id,profile_id), FOREIGN KEY(tenant_id,proposal_id) REFERENCES debate_proposals(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,profile_id) REFERENCES profiles(tenant_id,id), FOREIGN KEY(tenant_id,message_id) REFERENCES messages(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS debate_interjections(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, conversation_id TEXT NOT NULL, run_id TEXT NOT NULL, message_id TEXT NOT NULL, delivery_mode TEXT NOT NULL, context_epoch BIGINT NOT NULL, status TEXT NOT NULL, pinned INTEGER NOT NULL, command_key TEXT NOT NULL, digest TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL, UNIQUE(tenant_id,conversation_id,command_key), FOREIGN KEY(tenant_id,conversation_id) REFERENCES conversations(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,message_id) REFERENCES messages(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS debate_roster_changes(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, run_id TEXT NOT NULL, action TEXT NOT NULL, old_profile_id TEXT NOT NULL, new_profile_id TEXT NOT NULL, command_key TEXT NOT NULL, digest TEXT NOT NULL, status TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_utc TEXT NOT NULL, updated_utc TEXT NOT NULL, UNIQUE(tenant_id,run_id,command_key), FOREIGN KEY(tenant_id,run_id) REFERENCES runs(tenant_id,id) ON DELETE CASCADE);
""";
    }
}
